import React from 'react';
import { Link } from 'react-router-dom';
import { useApp } from '../lib/AppContext';
import StatCard from '../components/ui/StatCard';
import LiveReportMap from '../components/dashboard/LiveReportMap';
import LiveQueueFeed from '../components/dashboard/LiveQueueFeed';
import { CategoryChart, ResolutionChart } from '../components/dashboard/AnalyticsCharts';

export default function Dashboard() {
  const { reports } = useApp();
  const pending = reports.filter(report => ['SUBMITTED', 'UNDER_REVIEW'].includes(report.status)).length;
  const inProgress = reports.filter(report => report.status === 'IN_PROGRESS').length;
  const resolved = reports.filter(report => report.status === 'RESOLVED').length;
  return <><div className="page-heading"><div><div className="eyebrow">THURSDAY, OCTOBER 8, 2026</div><h1>Good morning, Thoko <span>✳</span></h1><p>Here’s what’s happening across your region today.</p></div><Link className="primary" to="/reports">View reports queue <span>→</span></Link></div><div className="stat-grid"><StatCard title="Total reports" value={String(reports.length).padStart(2, '0')} change="↑ 12%" note="vs. last month" icon="▤" tone="green"/><StatCard title="Pending review" value={String(pending).padStart(2, '0')} change="Needs attention" note="Review new cases" icon="◷" tone="amber"/><StatCard title="In progress" value={String(inProgress).padStart(2, '0')} change="Active cases" note="Across your region" icon="↗" tone="blue"/><StatCard title="Resolved cases" value={String(resolved).padStart(2, '0')} change="↑ 8%" note="vs. last month" icon="✓" tone="mint"/></div><div className="dashboard-grid"><LiveReportMap reports={reports}/><LiveQueueFeed reports={reports}/></div><div className="bottom-grid"><ResolutionChart/><CategoryChart/></div></>;
}
